import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c,u as l}from"./index-BXvM1dGO.js";var u={class:`about`},d={class:`back`},f=c({__name:`AboutView`,setup(c){return(c,f)=>(t(),n(`main`,u,[o(`article`,null,[f[1]||=e(`<header class="head" data-v-ed236b96><h1 data-v-ed236b96>关于这个检索</h1><p class="lead" data-v-ed236b96> 一个基于<strong data-v-ed236b96>阮一峰《科技爱好者周刊》</strong>的语义搜索工具。 把每一期「工具」「资源」板块里散落的几十条链接汇总到一个搜索框里，用自然语言描述需求即可定位往期推荐。 </p></header><section data-v-ed236b96><h2 data-v-ed236b96>怎么用</h2><p data-v-ed236b96> 在搜索框输入你想做的事，比如「图片压缩」「终端配色」「OCR 识别」，回车即可。 后端把 query 通过 embedding 模型编成向量，与库内所有工具的向量算余弦相似度，按分数排序后用三层阈值收敛展示。 </p></section><section data-v-ed236b96><h2 data-v-ed236b96>技术栈</h2><ul data-v-ed236b96><li data-v-ed236b96><strong data-v-ed236b96>前端：</strong>Vue 3 + Vite，无 UI 框架；结果区用 CSS <code data-v-ed236b96>column-count</code> 实现瀑布流</li><li data-v-ed236b96><strong data-v-ed236b96>后端：</strong>Flask 开发环境 + Gunicorn 生产环境（部署在 Render Web Service，免费实例）</li><li data-v-ed236b96><strong data-v-ed236b96>Embedding：</strong>阿里云 DashScope 远程 API（<code data-v-ed236b96>qwen3.7-text-embedding</code>，768 维）；查询与库向量使用同一模型保证向量空间一致</li><li data-v-ed236b96><strong data-v-ed236b96>数据源：</strong><a href="https://github.com/ruanyf/weekly" target="_blank" rel="noopener" data-v-ed236b96>github.com/ruanyf/weekly</a>，每期 <code data-v-ed236b96>issue-N.md</code> 中的「工具」章节</li></ul></section><section data-v-ed236b96><h2 data-v-ed236b96>字段说明</h2><p data-v-ed236b96>每张卡片顶部是工具标题（无外链时仅显示标题），右侧是该期发刊日期；描述区支持内联 Markdown 图片与链接；底部是来源 issue 文件名（链向阮一峰 GitHub 仓库）与相似度 score。卡片整体按相关度收敛展示，top 项最相关。</p></section>`,4),o(`p`,d,[s(l(i),{to:`/`},{default:r(()=>[...f[0]||=[a(`← 回到搜索`,-1)]]),_:1})])])]))}},[[`__scopeId`,`data-v-ed236b96`]]);export{f as default};